import {
  Column,
  Entity,
  Index,
  JoinColumn,
  ManyToOne,
  PrimaryColumn,
  Unique,
} from 'typeorm';
import { UserEntity } from 'src/user/models/user.entity';
import { API_CONTRACT } from 'src/common/api-contract';

/**
 * A personal access token (FEAT-07a), valid only on the MCP endpoint. The
 * secret is never stored: only the sha256 of its secret part. `id` is
 * generated by the service (randomUUID). Constraint names match migration
 * 1763300000000-PersonalAccessTokens.
 */
@Entity('personal_access_tokens')
@Unique('UQ_pat_prefix', ['prefix'])
@Index('IDX_pat_user', ['user_id'])
export class PersonalAccessTokenEntity {
  @PrimaryColumn({ type: 'uuid', primaryKeyConstraintName: 'PK_pat' })
  id!: string;

  @Column({ type: 'varchar' })
  user_id!: string;

  @Column({ type: 'varchar', length: API_CONTRACT.limits.tokenNameMax })
  name!: string;

  @Column({ type: 'varchar', length: 16 })
  prefix!: string;

  @Column({ type: 'char', length: 64 })
  secret_hash!: string;

  @Column({ type: 'varchar', length: 100, default: 'mcp' })
  scopes!: string;

  @Column({ type: 'timestamptz', default: () => 'now()' })
  created_at!: Date;

  @Column({ type: 'timestamptz', nullable: true })
  last_used_at!: Date | null;

  @Column({ type: 'timestamptz', nullable: true })
  expires_at!: Date | null;

  @Column({ type: 'timestamptz', nullable: true })
  revoked_at!: Date | null;

  @ManyToOne(() => UserEntity, { onDelete: 'CASCADE' })
  @JoinColumn({
    name: 'user_id',
    referencedColumnName: 'user_id',
    foreignKeyConstraintName: 'FK_pat_user',
  })
  user?: UserEntity;
}
